284: function enemyDamage(enemy, damage, knockback = .65) {
285:   if (!enemy.alive) return;
286:   enemy.hp = Math.max(0, enemy.hp - damage);
287:   enemy.hitAt = worldTime; enemy.bar.scale.x = Math.max(.001, enemy.hp / enemy.maxHp); enemy.bar.position.x = -.43 * (1 - enemy.hp / enemy.maxHp);
288:   enemy.root.position.x += Math.sin(enemy.root.rotation.y) * knockback;
289:   enemy.root.position.z += Math.cos(enemy.root.rotation.y) * knockback;
290:   enemy.root.traverse((child) => { if (child.isMesh && child.material.emissive) { child.material.emissive.set('#6b2317'); child.material.emissiveIntensity = .35; } });
291:   setTimeout(() => enemy.root.traverse((child) => { if (child.isMesh && child.material.emissive) child.material.emissiveIntensity = 0; }), 90);
292:   playTone(damage >= 80 ? 130 : 185, .09, 'sawtooth', .022);
293:   if (enemy.hp === 0) defeatEnemy(enemy);
294: }
